INSERT INTO god2_research._xjz_stage_client_message_template VALUES(1,1,'NPCBossMessage',NULL,'歡迎歡迎，本店接受各類武器防具的販賣交易。我們是老字號，師傅的技術有口皆碑，我們所製造的武器防具犀利又耐用。','','裝備屋(開始)','equipment_shop','開始',6,'["1","欢迎欢迎，本店接受各类武器防具的贩卖交易。我们是老字号，师傅的技术有口皆碑，我们所制造的武器防具犀利又耐用。","","","","装备屋(开始)"]','server_implementation/data/evidence_raw/message.csv',3,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(2,2,'NPCBossMessage',NULL,'歡迎光臨，本店接受各類武器防具的販賣交易。方圓百里之外的人們都知道本店販賣的武器防具質量最好。','','裝備屋(開始)','equipment_shop','開始',6,'["2","欢迎光临，本店接受各类武器防具的贩卖交易。方圆百里之外的人们都知道本店贩卖的武器防具质量最好。","","","","装备屋(开始)"]','server_implementation/data/evidence_raw/message.csv',4,'client_message_direct_nls_traditional',0);
