INSERT INTO god2_research._xjz_stage_client_message_template VALUES(10,10,'NPCBossMessage',NULL,'本店提供各類丹藥及合成素材販賣。出門在外難免跌打損傷，我販賣的各式丹藥是您身體健康的守護者。',NULL,'煉丹房(開始)','alchemy_shop','開始',6,'["10","本店提供各类丹药及合成素材贩卖。出门在外难免跌打损伤，我贩卖的各式丹药是您身体健康的守护者。","","","","炼丹房(开始)"]','server_implementation/data/evidence_raw/message.csv',12,'client_message_direct',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(11,11,'NPCBossMessage',NULL,'本店提供各類丹藥及合成素材販賣。我的丹藥遵循古法精制，不論外傷內傷一服見效。','','煉丹房(開始)','alchemy_shop','開始',6,'["11","本店提供各类丹药及合成素材贩卖。我的丹药遵循古法精制，不论外伤内伤一服见效。","","","","炼丹房(开始)"]','server_implementation/data/evidence_raw/message.csv',13,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(12,12,'NPCBossMessage',NULL,'俗話說忠言逆耳，良藥苦口，歡迎光臨敝店，本店提供各類丹藥及合成素材販賣。','','煉丹房(開始)','alchemy_shop','開始',6,'["12","俗话说忠言逆耳，良药苦口，欢迎光临敝店，本店提供各类丹药及合成素材贩卖。","","","","炼丹房(开始)"]','server_implementation/data/evidence_raw/message.csv',14,'client_message_direct_nls_traditional',0);
