INSERT INTO god2_research._xjz_stage_client_message_template VALUES(47,47,'NPCBossMessage',NULL,'我有技能書欲傳授給有緣人，但感覺上我對你並不投緣，所以請你拿錢來學。','','葛城奇人(開始)',NULL,'開始',6,'["47","我有技能书欲传授给有缘人，但感觉上我对你并不投缘，所以请你拿钱来学。","","","","葛城奇人(开始)"]','server_implementation/data/evidence_raw/message.csv',49,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(48,48,'NPCBossMessage',NULL,'師父領進門，修行在個人。自己專心研究，學不會別來找我退錢。','','葛城奇人(結束)',NULL,'結束',6,'["48","师父领进门，修行在个人。自己专心研究，学不会别来找我退钱。","","","","葛城奇人(结束)"]','server_implementation/data/evidence_raw/message.csv',50,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(49,49,'NPCBossMessage',NULL,'在未來遙遠的路途上面，喪命的陰影將無時無刻跟在你的身后，花些錢買我的技能書可以幫助你抵抗那些來自地獄的威脅。','','楓華鎮奇人',NULL,'',6,'["49","在未來遙遠的路途上面，喪命的陰影将無時無刻跟在你的身后，花些钱买我的技能书可以帮助你抵抗那些来自地狱的威胁。","","","","楓華鎮奇人"]','server_implementation/data/evidence_raw/message.csv',51,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(50,50,'NPCBossMessage',NULL,'技能書不是掛在身上的護身符，你要去使用它修習它，才能轉換成捍衛自己生命安全的保證。','','南巢鎮奇人',NULL,'',6,'["50","技能书不是挂在身上的护身符，你要去使用它修习它，才能转换成捍卫自己生命安全的保证。","","","","南巢镇奇人"]','server_implementation/data/evidence_raw/message.csv',52,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(51,51,'NPCBossMessage',NULL,'無微不至，無為而治，無洞不成府啊！你來找我是為了成立洞府一事嗎？成立洞府就等于宣布贛在起跑點了，不過前一百個成立的洞府才能獲得根據地。','','洞府會館(開始)',NULL,'開始',6,'["51","无微不至，无为而治，无洞不成府啊！你来找我是为了成立洞府一事吗?成立洞府就等于宣布赢在起跑点了，不过前一百个成立的洞府才能获得根据地。","","","","洞府会馆(开始)"]','server_implementation/data/evidence_raw/message.csv',53,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(52,52,'NPCBossMessage',NULL,'你已經完成初步的洞府成立手續，現在到外面去找的洞府星君，開啟你洞府根據地的通道。','','洞府會館(結束)',NULL,'結束',6,'["52","你已经完成初步的洞府成立手续，现在到外面去找的洞府星君，开启你洞府根据地的通道。","","","","洞府会馆(结束)"]','server_implementation/data/evidence_raw/message.csv',54,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(53,53,'NPCBossMessage',NULL,'對不起～ 您不符合轉生的條件！','','洞府土地婆(判斷沒資格到封神叅轉生)',NULL,'判斷沒資格到封神叅轉生',6,'["53","对不起～ 您不符合转生的条件！","","","","洞府土地婆(判断没资格到封神台转生)"]','server_implementation/data/evidence_raw/message.csv',55,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(54,54,'NPCBossMessage',NULL,'歡迎參觀啊，雖然你不是本洞府的成員。','','洞府土地公(判斷非同洞府玩家進入根據地)',NULL,'判斷非同洞府玩家進入根據地',6,'["54","欢迎参观啊，虽然你不是本洞府的成员。","","","","洞府土地公(判断非同洞府玩家进入根据地)"]','server_implementation/data/evidence_raw/message.csv',56,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(55,55,'NPCBossMessage',NULL,'我是看守死門的神將，只有封神叅遭到攻擊，死門才會打開。退后，現在不準進出此門。','','死門神將(沒有封神叅戰爭時的對話)',NULL,'沒有封神叅戰爭時的對話',6,'["55","我是看守死门的神将，只有封神台遭到攻击，死门才会打开。退后，现在不准进出此门。","","","","死门神将(沒有封神台战争时的对话)"]','server_implementation/data/evidence_raw/message.csv',57,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(56,56,'NPCBossMessage',NULL,'現在只有這個空間，我無法為你轉換至其他的空間。','','挪移力士(判斷無法傳送到其它樓層)',NULL,'判斷無法傳送到其它樓層',6,'["56","现在只有这个空间，我无法为你转换至其他的空间。","","","","挪移力士(判断无法传送到其它楼层)"]','server_implementation/data/evidence_raw/message.csv',58,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(57,57,'NPCBossMessage',NULL,'在有限的生命里我將追求永恒的夢想，法寶就是我夢寐以求朝思夕想的寶貝！我愿意散盡家財，一圓我蒐集普天下所有法寶的愿望，你有法寶要出售嗎？我要買！','','收藏家(交易開始)','special_trade_npc','交易開始',6,'["57","在有限的生命里我将追求永恒的梦想，法宝就是我梦寐以求朝思夕想的宝贝！我愿意散尽家财，一圆我搜集普天下所有法宝的愿望，你有法宝要出售吗？我要买！","","","","收藏家(交易开始)"]','server_implementation/data/evidence_raw/message.csv',59,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(58,58,'NPCBossMessage',NULL,'又有一個法寶正式成為我的寶貝！','','收藏家(交易結束)','special_trade_npc','交易結束',6,'["58","又有一个法宝正式成为我的宝贝！","","","","收藏家(交易结束)"]','server_implementation/data/evidence_raw/message.csv',60,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(59,59,'NPCBossMessage',NULL,'哈哈哈！天要下雨，娘要改嫁，我愛法寶，這都是沒辦法的事。如果你有要脫手的法寶，就快點賣給我吧！','','收藏家(交易開始)','special_trade_npc','交易開始',6,'["59","哈哈哈！天要下雨，娘要改嫁，我爱法宝，这都是没办法的事。如果你有要脱手的法宝，就快点卖给我吧！","","","","收藏家(交易开始)"]','server_implementation/data/evidence_raw/message.csv',61,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(60,60,'NPCBossMessage',NULL,'你有沒有看到我眼中充滿著喜悅的淚水？','','收藏家(交易結束)','special_trade_npc','交易結束',6,'["60","你有沒有看到我眼中充满着喜悦的泪水？","","","","收藏家(交易结束)"]','server_implementation/data/evidence_raw/message.csv',62,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(61,61,'NPCBossMessage',NULL,'我不了解命運為什麼讓我們相遇？因為你遇到我，不然下次我遇到的是你的陰魂。','','出外人(交易開始)','special_trade_npc','交易開始',6,'["61","我不了解命运为什么让我们相遇？因为你遇到我，不然下次我遇到的是你的阴魂。","","","","出外人(交易开始)"]','server_implementation/data/evidence_raw/message.csv',63,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(62,62,'NPCBossMessage',NULL,'終究，你會發覺在絕望無助的時刻，我就是雪中送炭的救星。','','出外人(交易開始)','special_trade_npc','交易開始',6,'["62","终究，你会发觉在绝望无助的时刻，我就是雪中送炭的救星。","","","","出外人(交易开始)"]','server_implementation/data/evidence_raw/message.csv',64,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(63,63,'NPCBossMessage',NULL,'你身上布滿著驚恐與死亡的塵灰，所以我等待，等待著你。','','出外人(交易開始)','special_trade_npc','交易開始',6,'["63","你身上布满着惊恐与死亡的尘灰，所以我等待，等待着你。","","","","出外人(交易开始)"]','server_implementation/data/evidence_raw/message.csv',65,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(64,64,'NPCBossMessage',NULL,'就像沙漠需要甘霖，就像黑夜需要星辰，就像戀愛需要對象，就像小鳥需要回巢，就像你需要出外人。','','出外人(交易開始)','special_trade_npc','交易開始',6,'["64","就像沙漠需要甘霖，就像黑夜需要星辰，就像恋爱需要对象，就像小鸟需要回巢，就像你需要出外人。","","","","出外人(交易开始)"]','server_implementation/data/evidence_raw/message.csv',66,'client_message_direct_nls_traditional',0);
INSERT INTO god2_research._xjz_stage_client_message_template VALUES(65,65,'NPCBossMessage',NULL,'不好意思啦～～雖然是新年，不過，你沒有紅包還是不能給你領錢的啦～～～','','',NULL,'',2,'["65","不好意思啦～～虽然是新年，不过，你沒有红包还是不能给你领钱的啦～～～"]','server_implementation/data/evidence_raw/message.csv',67,'client_message_direct_nls_traditional',0);
