-- 454_intake_xjz_client_message_security_csharp_evidence.sql
-- Purpose: ingest C# restored client message, service binding, security block, and forbidden-word evidence.
-- Source pack: XJZ-csharp-evidence-capture-pack-20260818.zip

DROP TABLE IF EXISTS god2_research._xjz_stage_client_message_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_client_message_service_binding;
DROP TABLE IF EXISTS god2_research._xjz_stage_client_security_block_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_forbidden_word_template;

CREATE TABLE god2_research._xjz_stage_client_message_template (
  message_row_id INT PRIMARY KEY,
  message_id INT NULL,
  source_section VARCHAR(96) NOT NULL,
  message_channel INT NULL,
  text_zh_tw TEXT NOT NULL,
  alt_text_zh_tw TEXT NULL,
  service_label_zh_tw VARCHAR(160) NULL,
  service_kind VARCHAR(96) NULL,
  service_phase_zh_tw VARCHAR(96) NULL,
  raw_column_count INT NOT NULL,
  raw_json LONGTEXT,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_client_message_service_binding (
  binding_id INT PRIMARY KEY,
  service_kind VARCHAR(96) NOT NULL,
  service_label_zh_tw VARCHAR(160) NOT NULL,
  service_phase_zh_tw VARCHAR(96) NULL,
  message_count INT NOT NULL,
  message_id_min INT NULL,
  message_id_max INT NULL,
  message_ids_json LONGTEXT,
  target_runtime_table VARCHAR(128) NULL,
  target_sample_table VARCHAR(128) NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line_min INT NULL,
  raw_line_max INT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_client_security_block_rule (
  rule_id INT PRIMARY KEY,
  rule_kind VARCHAR(96) NOT NULL,
  source_section VARCHAR(96) NOT NULL,
  pattern_text VARCHAR(255) NOT NULL,
  match_target VARCHAR(96) NOT NULL,
  detection_type INT NULL,
  detection_type_name VARCHAR(96) NULL,
  action_code INT NULL,
  action_name VARCHAR(96) NULL,
  message_id INT NULL,
  note_zh_tw TEXT NULL,
  raw_json LONGTEXT,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_forbidden_word_template (
  forbidden_word_id INT PRIMARY KEY,
  word_text_zh_tw VARCHAR(255) NOT NULL,
  normalized_key VARCHAR(255) NOT NULL,
  match_kind VARCHAR(64) NOT NULL,
  word_length INT NOT NULL,
  source_version VARCHAR(64) NULL,
  source_date VARCHAR(32) NULL,
  raw_json LONGTEXT,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS god2_research.xjz_client_message_template_evidence (
  message_row_id INT NOT NULL,
  message_id INT NULL,
  source_section_zh_tw VARCHAR(96) NOT NULL,
  message_channel INT NULL,
  text_zh_tw TEXT NOT NULL,
  alt_text_zh_tw TEXT NULL,
  service_label_zh_tw VARCHAR(160) NULL,
  service_kind_zh_tw VARCHAR(96) NULL,
  service_phase_zh_tw VARCHAR(96) NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (message_row_id),
  KEY ix_xjz_client_message_id (message_id),
  KEY ix_xjz_client_message_service (service_kind_zh_tw, service_phase_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：客戶端系統/NPC/服務訊息模板，僅保留可讀文字。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_client_message_service_binding_evidence (
  binding_id INT NOT NULL,
  service_kind_zh_tw VARCHAR(96) NOT NULL,
  service_label_zh_tw VARCHAR(160) NOT NULL,
  service_phase_zh_tw VARCHAR(96) NULL,
  message_count INT NOT NULL,
  message_id_min INT NULL,
  message_id_max INT NULL,
  message_ids_zh_tw TEXT NOT NULL,
  target_runtime_table_zh_tw VARCHAR(128) NULL,
  target_sample_table_zh_tw VARCHAR(128) NULL,
  source_line_min INT NULL,
  source_line_max INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (binding_id),
  UNIQUE KEY ux_xjz_message_service_binding (service_kind_zh_tw, service_label_zh_tw, service_phase_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：服務功能與客戶端訊息ID綁定。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_client_security_block_rule_evidence (
  rule_id INT NOT NULL,
  rule_kind_zh_tw VARCHAR(96) NOT NULL,
  source_section_zh_tw VARCHAR(96) NOT NULL,
  pattern_text_zh_tw VARCHAR(255) NOT NULL,
  match_target_zh_tw VARCHAR(96) NOT NULL,
  detection_type INT NULL,
  detection_type_name_zh_tw VARCHAR(96) NULL,
  action_code INT NULL,
  action_name_zh_tw VARCHAR(96) NULL,
  message_id INT NULL,
  note_zh_tw TEXT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (rule_id),
  KEY ix_xjz_security_pattern (pattern_text_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：客戶端工具阻擋與安全規則候選。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_forbidden_word_evidence (
  forbidden_word_id INT NOT NULL,
  word_text_zh_tw VARCHAR(255) NOT NULL,
  normalized_key_zh_tw VARCHAR(255) NOT NULL,
  match_kind_zh_tw VARCHAR(64) NOT NULL,
  word_length INT NOT NULL,
  source_version VARCHAR(64) NULL,
  source_date VARCHAR(32) NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (forbidden_word_id),
  KEY ix_xjz_forbidden_word_text (word_text_zh_tw),
  KEY ix_xjz_forbidden_word_key (normalized_key_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：聊天與命名禁詞候選，未直接啟用正式阻擋。';

DELETE FROM god2_research.xjz_client_message_template_evidence;
SELECT
  message_row_id,
  message_id,
  source_section,
  message_channel,
  text_zh_tw,
  alt_text_zh_tw,
  service_label_zh_tw,
  CASE service_kind
    WHEN 'equipment_shop' THEN '裝備商店'
    WHEN 'item_shop' THEN '道具商店'
    WHEN 'warehouse' THEN '倉庫'
    WHEN 'quest' THEN '任務'
    ELSE service_kind END,
  service_phase_zh_tw,
  raw_line,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_client_message_template;

DELETE FROM god2_research.xjz_client_message_service_binding_evidence;
SELECT
  binding_id,
  CASE service_kind
    WHEN 'equipment_shop' THEN '裝備商店'
    WHEN 'item_shop' THEN '道具商店'
    WHEN 'warehouse' THEN '倉庫'
    WHEN 'quest' THEN '任務'
    ELSE service_kind END,
  service_label_zh_tw,
  service_phase_zh_tw,
  message_count,
  message_id_min,
  message_id_max,
  message_ids_json,
  target_runtime_table,
  target_sample_table,
  raw_line_min,
  raw_line_max,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_client_message_service_binding;

DELETE FROM god2_research.xjz_client_security_block_rule_evidence;
SELECT
  rule_id,
  CASE rule_kind WHEN 'tool_block' THEN '工具阻擋' ELSE rule_kind END,
  source_section,
  pattern_text,
  CASE match_target WHEN 'title' THEN '視窗標題' ELSE match_target END,
  detection_type,
  CASE detection_type_name WHEN 'title' THEN '視窗標題' ELSE detection_type_name END,
  action_code,
  CASE action_name WHEN 'quit' THEN '離開遊戲' ELSE action_name END,
  message_id,
  note_zh_tw,
  raw_line,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_client_security_block_rule;

DELETE FROM god2_research.xjz_forbidden_word_evidence;
SELECT
  forbidden_word_id,
  word_text_zh_tw,
  normalized_key,
  CASE match_kind WHEN 'contains' THEN '包含比對' ELSE match_kind END,
  word_length,
  source_version,
  source_date,
  raw_line,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_forbidden_word_template;

CREATE OR REPLACE VIEW god2_research.vw_xjz_client_message_security_summary_zh_tw AS
SELECT '客戶端訊息模板' AS 資料類型, COUNT(*) AS 筆數, SUM(needs_packet_evidence) AS 需要封包證據, NULL AS 已綁服務, NULL AS 備註
FROM god2_research.xjz_client_message_template_evidence
UNION ALL
SELECT '服務訊息綁定', COUNT(*), SUM(needs_packet_evidence), COUNT(*), '用於服務端提示文字與NPC/商店/任務訊息對照'
FROM god2_research.xjz_client_message_service_binding_evidence
UNION ALL
SELECT '安全阻擋規則', COUNT(*), SUM(needs_packet_evidence), NULL, '候選規則，未直接啟用正式踢線或封鎖'
FROM god2_research.xjz_client_security_block_rule_evidence
UNION ALL
SELECT '聊天命名禁詞', COUNT(*), SUM(needs_packet_evidence), NULL, '候選禁詞，未直接啟用正式阻擋'
FROM god2_research.xjz_forbidden_word_evidence;

CREATE OR REPLACE VIEW god2_research.vw_xjz_client_message_security_simplified_scan_zh_tw AS
SELECT '客戶端訊息模板' AS 資料表, COUNT(*) AS 疑似簡體殘留
FROM god2_research.xjz_client_message_template_evidence
WHERE text_zh_tw REGEXP '[简体国庆黄金周欢迎类卖们圆质给]'
UNION ALL
SELECT '聊天命名禁詞', COUNT(*)
FROM god2_research.xjz_forbidden_word_evidence
WHERE word_text_zh_tw REGEXP '[简体国庆黄金周欢迎类卖们圆质给]'
UNION ALL
SELECT '安全阻擋規則', COUNT(*)
FROM god2_research.xjz_client_security_block_rule_evidence
WHERE pattern_text_zh_tw REGEXP '[简体国庆黄金周欢迎类卖们圆质给]';

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入客戶端訊息模板與服務綁定',
    safe_apply_level_zh_tw = '可用於服務端提示文字對照；正式覆蓋需逐服務確認',
    next_server_action_zh_tw = '比對現有服務端錯誤碼、NPC商店、任務提示，缺文字時優先引用這批繁體訊息模板。',
    blocked_reason_zh_tw = '不同服務情境可能共用訊息ID，不能無條件覆蓋正式提示。',
    related_project_object_zh_tw = 'migration 454, xjz_client_message_*'
WHERE evidence_key = 'client_message_templates';

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入聊天命名禁詞與安全阻擋候選',
    safe_apply_level_zh_tw = '可用於研究與人工審核；正式阻擋需分級開關',
    next_server_action_zh_tw = '先建立聊天/命名檢查服務的唯讀審核模式，確認不誤殺後再啟用正式阻擋。',
    blocked_reason_zh_tw = '禁詞和工具阻擋可能誤判，不能直接全量踢線或封鎖。',
    related_project_object_zh_tw = 'migration 454, xjz_forbidden_word_evidence, xjz_client_security_block_rule_evidence'
WHERE evidence_key = 'forbidden_words';

DROP TABLE IF EXISTS god2_research._xjz_stage_client_message_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_client_message_service_binding;
DROP TABLE IF EXISTS god2_research._xjz_stage_client_security_block_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_forbidden_word_template;